insert into public.produtos (id, nome, categoria, descricao, fotos, preco, disponibilidade, prazo, durabilidade, cuidados, ocasioes, cores, ativo) values
  ('vaso-terracota-capim', 'Vaso terracota com capim laranja', 'Vasos', 'Vaso de terracota com capim desidratado em tom laranja queimado. Uma peça para dar calor a estantes, aparadores e mesas de apoio.', array['imagens/web/capim5.webp']::text[], 129, 'disponivel', 'Pronta entrega em Tubarão (SC)', 'Mais de 1 ano com os cuidados indicados', 'Mantenha longe de água, umidade e sol direto. Tire o pó com pincel macio ou ar frio do secador.', array['Decoração', 'Aniversário']::text[], array['Terracota', 'Laranja']::text[], true),
  ('vaso-branco-esculpido', 'Vaso branco esculpido com flores', 'Vasos', 'Vaso branco esculpido com composição de flores desidratadas em tons neutros, finalizado com etiqueta do ateliê.', array['imagens/web/capim6.webp']::text[], 189, 'disponivel', 'Pronta entrega em Tubarão (SC)', 'Mais de 1 ano com os cuidados indicados', 'Evite umidade e luz solar direta. Não borrife água nem produtos sobre as flores.', array['Presente', 'Decoração', 'Agradecimento']::text[], array['Neutros', 'Creme']::text[], true),
  ('difusor-flores-vinho', 'Difusor com raminho de flores vinho', 'Presentes', 'Difusor de ambiente com raminho de flores desidratadas em vinho sobre base de madeira. Um mimo perfumado e duradouro.', array['imagens/web/capim4.webp']::text[], 79, 'disponivel', 'Pronta entrega em Tubarão (SC)', 'As flores duram mais de 1 ano; o aroma depende do refil', 'Mantenha em local ventilado e longe de água. Reponha a essência conforme o uso.', array['Presente', 'Agradecimento', 'Aniversário']::text[], array['Vinho', 'Neutros']::text[], true),
  ('buque-presente-vivo', 'Buquê desidratado para presente', 'Buquês', 'Buquê de flores desidratadas montado à mão, feito para presentear quem você ama sem pressa de ver as flores murcharem.', array['imagens/web/oficina-presente-vivo.webp']::text[], 159, 'sob-encomenda', 'Produção em até 5 dias úteis', 'Mais de 1 ano com os cuidados indicados', 'Guarde fora do sol e da umidade. Pode ser mantido no vaso ou pendurado de cabeça para baixo.', array['Aniversário', 'Datas comemorativas', 'Presente']::text[], array['Vinho', 'Creme', 'Neutros']::text[], true),
  ('arranjo-vaso-personalizado', 'Arranjo de vaso personalizado', 'Arranjos', 'Arranjo criado sob medida: você escolhe ocasião, cores e tamanho e o ateliê monta a composição e escolhe o vaso.', array['imagens/web/oficina-arranjo-vaso.webp']::text[], null, 'sob-encomenda', 'Produção em 5 a 10 dias úteis, conforme o projeto', 'Mais de 1 ano com os cuidados indicados', 'Evite sol direto, umidade e vento forte. Limpe com pincel macio.', array['Decoração', 'Aniversário', 'Presente corporativo']::text[], array['Sob medida']::text[], true),
  ('guirlanda-desidratada', 'Guirlanda de flores desidratadas', 'Decoração', 'Guirlanda artesanal para portas e paredes, com flores e folhagens desidratadas em composição natural.', array['imagens/web/oficina-guirlanda.webp']::text[], 220, 'sob-encomenda', 'Produção em até 7 dias úteis', 'Mais de 1 ano em ambientes internos', 'Use em área coberta, longe de chuva e umidade. Pendure com cuidado para não quebrar as hastes.', array['Decoração', 'Datas comemorativas']::text[], array['Verde', 'Neutros', 'Terracota']::text[], true),
  ('composicao-estudio-creme', 'Composição de estúdio em creme e dourado', 'Arranjos', 'Composição de flores preservadas em creme, dourado e vinho, para presentear ou decorar ambientes com elegância.', array['imagens/web/capim1.webp', 'imagens/web/capim2.webp']::text[], 260, 'indisponivel', 'Sem previsão no momento', 'Mais de 1 ano com os cuidados indicados', 'Mantenha longe de água e umidade, e evite sol direto.', array['Decoração', 'Presente corporativo', 'Presente']::text[], array['Creme', 'Dourado', 'Vinho']::text[], true)
